924	/// RIFF container: `RIFF`, a little-endian chunk size, then a four-character
925	/// FORM type naming what the container actually holds. Requiring a known FORM
926	/// is what separates a WAV from a sentence that opens with the word "RIFF".
927	///
928	/// `ACON` is the animated-cursor FORM. It is listed because `ANI ` — which was
929	/// here on its own — is the file EXTENSION, not the FORM type, and no encoder
930	/// writes it: swept over every RIFF file on the build machine (195 files;
931	/// FORM types `WAVE` 158, `WEBP` 25, `ACON` 12), the closed set without `ACON`
932	/// refused all 12 real `.ani` files. Same defect shape as #379 one row up, so
933	/// it is corrected here rather than left for the closed set to be widened a
934	/// third time.
935	fn riff_form(prefix: &[u8]) -> bool {
936	    prefix.len() >= 12
937	        && matches!(
938	            &prefix[8..12],
939	            b"WAVE" | b"AVI " | b"WEBP" | b"RMID" | b"ACON" | b"CDDA" | b"PAL " | b"RDIB"
940	        )
941	}
