969	/// ID3v2 tag header: `ID3`, a major version (2, 3 and 4 are the versions that
970	/// exist), a revision that is not the reserved 0xFF, a flags byte, and a
971	/// four-byte SYNCHSAFE size whose bytes each have the top bit clear.
972	///
973	/// Unqualified, this signature is three ASCII letters: a CSV whose first
974	/// column header is `ID3` classified `Csv` on `ca4d75a` and `Binary` on this
975	/// branch until the version byte was checked.
976	fn id3v2_header(prefix: &[u8]) -> bool {
977	    prefix.len() >= 10
978	        && matches!(prefix[3], 2..=4)
979	        && prefix[4] != 0xff
980	        && prefix[6..10].iter().all(|b| *b < 0x80)
981	}
