1075	/// What to tell the user about a file that is an ARCHIVE, or `None` for any
1076	/// other binary kind.
1077	///
1078	/// autoindex never opens archives: unpacking is unbounded work on untrusted
1079	/// input (zip bombs, path traversal, a 50 GB Takeout part inflating into the
1080	/// state directory), and the honest alternative to doing that badly is saying
1081	/// so. "binary content (zip)" is true and useless to someone whose entire
1082	/// Google Takeout download is that one file — so the reason names the action.
1083	pub fn archive_advice(binary_kind: &str, gzip: bool) -> Option<String> {
1084	    let (what, how) = match (binary_kind, gzip) {
1085	        ("zip", _) => ("zip archive", "unzip <file>"),
1086	        ("tar", true) => ("gzip-compressed tar archive", "tar -xzf <file>"),
1087	        ("tar", false) => ("tar archive", "tar -xf <file>"),
1088	        ("7z", _) => ("7z archive", "7z x <file>"),
1089	        ("rar", _) => ("rar archive", "unrar x <file>"),
1090	        ("xz", _) => (
1091	            "xz-compressed file",
1092	            "xz -dk <file>, or tar -xJf <file> for a .tar.xz",
1093	        ),
1094	        _ => return None,
1095	    };
1096	    Some(format!(
1097	        "unextracted {what}: autoindex does not open archives — extract it first ({how}), \
1098	         then run autoindex on the extracted folder"
1099	    ))
1100	}
