1102	fn decode(bytes: &[u8]) -> (String, &'static str) {
1103	    match std::str::from_utf8(bytes) {
1104	        Ok(s) => (s.to_string(), "utf-8"),
1105	        Err(e) => {
1106	            // Tolerate a multi-byte char cut at the prefix boundary.
1107	            if e.valid_up_to() + 4 >= bytes.len() {
1108	                (
1109	                    String::from_utf8_lossy(&bytes[..e.valid_up_to()]).into_owned(),
1110	                    "utf-8",
1111	                )
1112	            } else {
1113	                let (s, _, _) = encoding_rs::WINDOWS_1252.decode(bytes);
1114	                (s.into_owned(), WINDOWS_1252_LOSSY)
1115	            }
1116	        }
1117	    }
1118	}
