1125	fn classify_text(text: &str, nonblank: &[&str]) -> Family {
1126	    // Email wins first: an RFC 5322 message opens with a header block whose lines
1127	    // (`From:`/`Date:`/`Message-ID:`/…) would otherwise be misread as prose or a
1128	    // key:value log. Gated on a STRONG header plus >=3 canonical headers so an
1129	    // ordinary `key: value` config or YAML never trips it.
1130	    // A mailbox is an email with a separator line in front of it, so it is
1131	    // tested first: the separator is not a header, and without this branch the
1132	    // `looks_like_email` gate below fails on line one and a multi-GB mailbox
1133	    // falls through to prose — every message's headers indexed as body text and
1134	    // the record cap cutting it off after the first few thousand sections.
1135	    if looks_like_mbox(nonblank) {
1136	        return Family::Mbox;
1137	    }
1138	    if looks_like_email(nonblank) {
1139	        return Family::Eml;
1140	    }
1141	
1142	    // Structured families (JSON/HTML/XML/logs/SQL/CSV) win first, for the whole
1143	    // file and — via the #551 frontmatter lookahead below — for a frontmatter
1144	    // body too.
1145	    if let Some(family) = classify_structured(text, nonblank) {
1146	        return family;
1147	    }
1148	
1149	    // YAML — but a leading `---` is also the opening delimiter of markdown/prose
1150	    // frontmatter (Jekyll, Hugo, Obsidian, Docusaurus, MkDocs, Astro, and Claude
1151	    // Code skill files — including the two this repo ships). Without a lookahead
1152	    // for the *closing* `---` and what follows it, every such file was handed to
1153	    // the YAML extractor, which keeps the frontmatter mapping and the first
1154	    // paragraph and discards the rest of the body (#551, silent data loss). If
1155	    // the file opens with `---`, has a matching closing `---`, and the body after
1156	    // it is not itself YAML, classify by that body so the whole document is
1157	    // indexed. A pure/multi-document YAML file keeps YAML: the content after its
1158	    // `---` document marker is still YAML — judged on line shape first and, when
1159	    // that is inconclusive, by whether the body actually parses as a YAML stream
1160	    // (#587).
1161	    let leads_with_marker = nonblank.first().map(|l| l.trim() == "---").unwrap_or(false);
1162	    if leads_with_marker {
1163	        if let Some(close_offset) = nonblank.iter().skip(1).position(|l| l.trim() == "---") {
1164	            let body = &nonblank[close_offset + 2..];
1165	            // #587 item 3: this guard used to demand `body.len() >= 2`, so a
1166	            // frontmatter file with a single non-blank body line still went to
1167	            // the YAML extractor, which keeps the frontmatter mapping and drops
1168	            // that line. One line is enough to judge on its shape.
1169	            if !body.is_empty() && yaml_like_count(body) * 2 < body.len() {
1170	                let body_text = body.join("\n");
1171	                // #587 item 1: classify the body by its real structured family
1172	                // (JSON/CSV/HTML/logs/SQL), not prose-only, so a
1173	                // frontmatter-over-CSV/JSON body matches its frontmatter-less
1174	                // twin. `classify_structured` never re-enters this
1175	                // YAML/frontmatter branch, so a recursive frontmatter parse
1176	                // cannot occur. It runs before the parse tier below because
1177	                // JSON *is* valid YAML — measured over 36,936 real
1178	                // frontmatter-shaped files, putting the parse first pulled 341
1179	                // JSON bodies and one XML body back into `Yaml` and undid #587
1180	                // item 1 for them.
1181	                if let Some(family) = classify_structured(&body_text, body) {
1182	                    return family;
1183	                }
1184	                // #587 item 2: the line-shape test above is not enough on its
1185	                // own — a genuine multi-document YAML stream whose later
1186	                // document is dominated by block scalars, comments and
1187	                // continuation lines fails it and was re-classified as prose,
1188	                // losing its per-document key structure. Parse the body: a real
1189	                // stream parses, a markdown body does not (`parses_as_yaml_stream`).
1190	                if !parses_as_yaml_stream(&body_text) {
1191	                    return txt_kind(body);
1192	                }
1193	                // else: a real YAML stream — fall through to `Family::Yaml`.
1194	            }
1195	        }
1196	    }
1197	    if leads_with_marker || yaml_line_ratio(nonblank) >= 0.6 {
1198	        return Family::Yaml;
1199	    }
1200	
1201	    txt_kind(nonblank)
1202	}
