1204	/// Header name of an RFC 5322 header line (`From`, `Content-Type`, `X-Mailer`),
1205	/// or `None` if the line is not `Name: …` with an RFC 822 field name.
1206	fn header_name(line: &str) -> Option<&str> {
1207	    let colon = line.find(':')?;
1208	    let name = &line[..colon];
1209	    if name.is_empty()
1210	        || !name.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-')
1211	        || !name.as_bytes()[0].is_ascii_alphabetic()
1212	    {
1213	        return None;
1214	    }
1215	    Some(name)
1216	}
