1218	/// Does this text open like an mbox mailbox? The first line must be a real
1219	/// separator (`From <sender> <asctime date>` — `extract::mbox::is_from_line`,
1220	/// the same predicate the splitter cuts on, so the two can never disagree about
1221	/// what a mailbox is) AND what follows it must pass the email gate. Detected by
1222	/// content, never by the `.mbox` extension: Thunderbird folders have no
1223	/// extension at all, Apple Mail's file is literally named `mbox`, and a
1224	/// `notes.mbox` that is not a mailbox must not be split as one.
1225	fn looks_like_mbox(nonblank: &[&str]) -> bool {
1226	    match nonblank.split_first() {
1227	        Some((first, rest)) => {
1228	            // A UTF-8 BOM in front of the first separator is still a mailbox;
1229	            // the splitter drops the same three bytes at offset 0.
1230	            let first = first.strip_prefix('\u{feff}').unwrap_or(first);
1231	            crate::extract::mbox::is_from_line(first.as_bytes()) && looks_like_email(rest)
1232	        }
1233	        None => false,
1234	    }
1235	}
1236	
1237	/// Does this text open like an email? Requires the first line to be a header, a
1238	/// STRONG header (`From`/`Date`/`Message-ID`/`Received`/…) somewhere in the
1239	/// opening block, and at least three canonical email headers total — enough to
1240	/// separate a real message from a `key: value` config that merely uses colons.
1241	fn looks_like_email(nonblank: &[&str]) -> bool {
1242	    const STRONG: &[&str] = &[
1243	        "from",
1244	        "date",
1245	        "message-id",
1246	        "received",
1247	        "return-path",
1248	        "delivered-to",
1249	        "dkim-signature",
1250	    ];
1251	    const KNOWN: &[&str] = &[
1252	        "from",
1253	        "to",
1254	        "cc",
1255	        "bcc",
1256	        "subject",
1257	        "date",
1258	        "message-id",
1259	        "received",
1260	        "return-path",
1261	        "reply-to",
1262	        "in-reply-to",
1263	        "references",
1264	        "mime-version",
1265	        "content-type",
1266	        "content-transfer-encoding",
1267	        "content-disposition",
1268	        "delivered-to",
1269	        "dkim-signature",
1270	        "sender",
1271	        "list-id",
1272	        "authentication-results",
1273	        "x-mailer",
1274	    ];
1275	    if !nonblank
1276	        .first()
1277	        .map(|l| header_name(l).is_some())
1278	        .unwrap_or(false)
1279	    {
1280	        return false;
1281	    }
1282	    let mut strong = false;
1283	    let mut known = 0usize;
1284	    for line in nonblank.iter().take(50) {
1285	        // Folded continuation lines (leading whitespace) are part of the header
1286	        // block; the first line that is neither a header nor a fold is the body.
1287	        let is_fold = line.starts_with(' ') || line.starts_with('\t');
1288	        match header_name(line) {
1289	            Some(name) => {
1290	                let n = name.to_ascii_lowercase();
1291	                if KNOWN.contains(&n.as_str()) {
1292	                    known += 1;
1293	                }
1294	                if STRONG.contains(&n.as_str()) {
1295	                    strong = true;
1296	                }
1297	            }
1298	            None if is_fold => {}
1299	            None => break,
1300	        }
1301	    }
1302	    strong && known >= 3
1303	}
