1305	/// The structured-family branches of [`classify_text`] — JSON/JSONL, HTML/XML,
1306	/// logs, SQL dump, CSV — returning the first family that matches, or `None` to
1307	/// continue to the YAML/prose fallbacks.
1308	///
1309	/// Extracted (#587) so the #551 frontmatter lookahead can classify its body by
1310	/// the *same* structured rules rather than prose-only: before this, a
1311	/// frontmatter-over-CSV/JSON file was classified `TxtProse` while its
1312	/// frontmatter-less twin was `Csv`/`Json`. It intentionally does **not** look
1313	/// at YAML or the `---` frontmatter marker, so running it over a body cannot
1314	/// recurse back into the frontmatter lookahead.
1315	fn classify_structured(text: &str, nonblank: &[&str]) -> Option<Family> {
1316	    let trimmed = text.trim_start();
1317	    // A lone `[section]` opening line that does not parse as JSON is a
1318	    // TOML/INI table header (`[package]` in Cargo.toml, `[Unit]` in a
1319	    // systemd unit), not a JSON array. Without this guard every such file
1320	    // fell into the JSON branch below (any '['-opener passes
1321	    // `looks_like_json_start`), reached the JSON extractor, and was junked
1322	    // — which, for Cargo.toml, also silently disabled the cratecite
1323	    // detector on every real repository (its crate table only holds
1324	    // indexed files). Live-verified 2026-07-30: three Cargo.tomls junked
1325	    // as "json candidate family" before this guard, indexed after.
1326	    let ini_table_header = nonblank.first().is_some_and(|l| {
1327	        let t = l.trim();
1328	        t.starts_with('[')
1329	            && t.ends_with(']')
1330	            && serde_json::from_str::<serde_json::Value>(t).is_err()
1331	    });
1332	    // JSON / JSONL
1333	    if !ini_table_header && (trimmed.starts_with('{') || trimmed.starts_with('[')) {
1334	        if nonblank.len() >= 2 {
1335	            let parse_ok = nonblank
1336	                .iter()
1337	                .filter(|l| serde_json::from_str::<serde_json::Value>(l).is_ok())
1338	                .count();
1339	            if parse_ok * 10 >= nonblank.len() * 9 {
1340	                return Some(Family::Jsonl);
1341	            }
1342	        } else if nonblank.len() == 1
1343	            && serde_json::from_str::<serde_json::Value>(nonblank[0]).is_ok()
1344	        {
1345	            // single complete JSON line — treat as JSON value file
1346	            return Some(Family::Json);
1347	        }
1348	        // Pretty-printed or multi-line JSON value.
1349	        if looks_like_json_start(trimmed) {
1350	            return Some(Family::Json);
1351	        }
1352	    }
1353	
1354	    // HTML / XML — declaration within the first 256 bytes.
1355	    let head_lc: String = text.chars().take(256).collect::<String>().to_lowercase();
1356	    if head_lc.contains("<!doctype html") || head_lc.contains("<html") {
1357	        return Some(Family::Html);
1358	    }
1359	    if head_lc.contains("<?xml") || (trimmed.starts_with('<') && text.contains("</")) {
1360	        // xhtml disguised as xml?
1361	        let lc: String = text.to_lowercase();
1362	        if lc.contains("<html") || lc.contains("<body") {
1363	            return Some(Family::Html);
1364	        }
1365	        return Some(Family::Xml);
1366	    }
1367	
1368	    // Log lines
1369	    if nonblank.len() >= 3 {
1370	        let hits = nonblank
1371	            .iter()
1372	            .filter(|l| crate::extract::logs::probe_line(l))
1373	            .count();
1374	        if hits * 10 >= nonblank.len() * 6 {
1375	            return Some(Family::Logs);
1376	        }
1377	    }
1378	
1379	    // SQL dump
1380	    let upper: String = text.chars().take(4096).collect::<String>().to_uppercase();
1381	    if (upper.contains("CREATE TABLE") || upper.contains("INSERT INTO")) && text.contains(';') {
1382	        return Some(Family::SqlDump);
1383	    }
1384	
1385	    // CSV — dialect probe happens in caller; here just a cheap plausibility test.
1386	    if nonblank.len() >= 2 && sniff_csv_dialect(nonblank).is_some() {
1387	        return Some(Family::Csv);
1388	    }
1389	
1390	    None
1391	}
