1393	fn looks_like_json_start(t: &str) -> bool {
1394	    // starts with { or [ and the first ~200 chars look like JSON tokens
1395	    let head: String = t.chars().take(200).collect();
1396	    head.contains(':') || head.contains('[') || head.contains('{')
1397	}
