1399	fn yaml_line_ratio(nonblank: &[&str]) -> f64 {
1400	    if nonblank.len() < 3 {
1401	        return 0.0;
1402	    }
1403	    yaml_like_count(nonblank) as f64 / nonblank.len() as f64
1404	}
