1406	/// Count of lines that read as YAML mapping/sequence entries. Shared by
1407	/// `yaml_line_ratio` and the frontmatter lookahead (#551) so both apply the
1408	/// identical definition of "YAML-like line" — unlike `yaml_line_ratio` this has
1409	/// no `< 3` short-circuit, so a short frontmatter body is judged on its content.
1410	fn yaml_like_count(lines: &[&str]) -> usize {
1411	    let re = regex::Regex::new(r"^\s*(- )?[\w.@/-]+:(\s|$)").unwrap();
1412	    lines
1413	        .iter()
1414	        .filter(|l| {
1415	            let t = l.trim_start();
1416	            // Markdown task-list items (`- [ ]` / `- [x]`) are NOT YAML
1417	            // evidence: `- [ ] text` is invalid YAML (flow sequence followed
1418	            // by a scalar), while checklists are everywhere in real notes.
1419	            // Counting them here routed whole checklist files into the YAML
1420	            // extractor, which can only junk-file them.
1421	            let checkbox =
1422	                t.starts_with("- [ ] ") || t.starts_with("- [x] ") || t.starts_with("- [X] ");
1423	            re.is_match(l) || (t.starts_with("- ") && !checkbox)
1424	        })
1425	        .count()
1426	}
