1484	fn txt_kind(nonblank: &[&str]) -> Family {
1485	    if nonblank.is_empty() {
1486	        return Family::TxtLines;
1487	    }
1488	    // NOTE — a whitespace-density guard ("text over 4 KiB with under 5%
1489	    // whitespace is pixel soup, junk it") was proposed here to catch raw TGA
1490	    // and `.bytes` payloads that decode into printable characters. It is not
1491	    // present, deliberately, because low whitespace density does not mean
1492	    // "not text":
1493	    //
1494	    //   * Chinese, Japanese, Korean, Thai, Lao, Khmer and Burmese prose is
1495	    //     scriptio continua — `nonblank` comes from `text.lines()`, so the
1496	    //     newlines are already stripped and only INTRA-LINE whitespace counts,
1497	    //     which those scripts do not have. Every such document over ~4 KiB
1498	    //     would be junked, in every corpus, worldwide.
1499	    //   * base64 blobs, hex dumps, FASTA/genomic sequences, single-line
1500	    //     minified payloads and long-token files are all legitimate text with
1501	    //     near-zero whitespace.
1502	    //   * `failure_resume_http_tests::legacy_key_collision_fails_before_
1503	    //     visibility_with_scoped_guidance` builds a 65,537-byte fixture of one
1504	    //     repeated ASCII letter. With the guard in place that file sniffs as
1505	    //     binary and the run exits 3 instead of 0 — the false positive is
1506	    //     reachable from this repo's own suite.
1507	    //
1508	    // A real TGA is caught by `looks_like_tga_header` in `sniff_bytes`, on the
1509	    // structure of its 18-byte header. The byte-statistics version of that
1510	    // check ("mostly non-ASCII under the windows-1252 fallback") was tried and
1511	    // removed in the same breath as this one and for the same reason: it
1512	    // junked Cyrillic, Greek, Hebrew, Arabic and mixed Japanese prose.
1513	    // Bounding what a magic-less binary costs is the right fix for the concern
1514	    // those guards existed for; silently deleting files that look unusual is
1515	    // not. Tracked as #381, which measures the gap this NOTE leaves open: a
1516	    // 4,194,495-byte printable NUL-free blob sniffs `txt-prose` and expands
1517	    // into 2048 indexed records.
1518	    let avg_len = nonblank.iter().map(|l| l.len()).sum::<usize>() as f64 / nonblank.len() as f64;
1519	    if avg_len > 60.0 {
1520	        return Family::TxtProse;
1521	    }
1522	    // A handful of short lines in a note-like file is still prose.
1523	    if nonblank.len() <= 5 {
1524	        return Family::TxtProse;
1525	    }
1526	
1527	    // Line LENGTH alone splits documents of the same kind.  A markdown
1528	    // postmortem with `## Headings` averages ~50 chars over 7 lines and used
1529	    // to land in TxtLines, while a 5-line runbook averaging 59 chars landed in
1530	    // TxtProse — same content type, two different families, therefore two
1531	    // different datasets with two different field names (`text` vs `body`).
1532	    // Cross-index BM25 statistics are then incomparable and a caller has to
1533	    // query both fields.
1534	    //
1535	    // Sentence density is the property that actually distinguishes a document
1536	    // from a record stream: prose lines end in terminal punctuation, whereas
1537	    // log lines, CSV rows and source code do not.  Measured on a mixed corpus:
1538	    // markdown 0.43-0.57, nginx access logs 0.00, syslog 0.20, Rust/Python/JS
1539	    // source 0.00-0.10.
1540	    let sentences = nonblank
1541	        .iter()
1542	        .filter(|l| {
1543	            let t = l.trim_end();
1544	            t.ends_with('.') || t.ends_with('!') || t.ends_with('?')
1545	        })
1546	        .count();
1547	    let sentence_ratio = sentences as f64 / nonblank.len() as f64;
1548	    if sentence_ratio >= 0.40 {
1549	        return Family::TxtProse;
1550	    }
1551	
1552	    // Hard-wrapped markdown rescue. Sentence density per LINE undercounts
1553	    // prose whose author wraps at ~70-80 columns: sentences end mid-line, so
1554	    // a five-paragraph note with a `# Title` scores ~0.30 and landed in
1555	    // TxtLines — which silently cost it its title, its section anchors, and
1556	    // (second brain) its wikilink detection. Content evidence, not the
1557	    // extension: a file that OPENS with an ATX heading and shows either
1558	    // markdown link syntax or some terminal punctuation is a markdown
1559	    // document. The heading-opener requirement keeps shebang'd scripts
1560	    // (`#!…`) and most code/config out; the second signal keeps out comment
1561	    // banners over pure record streams.
1562	    let md_link = nonblank
1563	        .iter()
1564	        .any(|l| l.contains("[[") || l.contains("]("));
1565	    if md_heading(nonblank[0]) && (md_link || sentence_ratio >= 0.20) {
1566	        return Family::TxtProse;
1567	    }
1568	    Family::TxtLines
1569	}
