1571	/// `# Title` … `###### Title` — an ATX markdown heading (1-6 `#`, a space,
1572	/// then text). `#!/bin/sh` and bare `#` fail the space-then-text rule.
1573	fn md_heading(line: &str) -> bool {
1574	    let t = line.trim_start();
1575	    let hashes = t.bytes().take_while(|&b| b == b'#').count();
1576	    (1..=6).contains(&hashes) && t.as_bytes().get(hashes) == Some(&b' ') && t.len() > hashes + 1
1577	}
