1579	/// Quote-aware field split (supports " and ' quoting).
1580	fn split_quoted(line: &str, delim: u8) -> Vec<String> {
1581	    let mut fields = Vec::new();
1582	    let mut cur = String::new();
1583	    let mut quote: Option<char> = None;
1584	    for c in line.chars() {
1585	        match quote {
1586	            Some(q) => {
1587	                if c == q {
1588	                    quote = None;
1589	                } else {
1590	                    cur.push(c);
1591	                }
1592	            }
1593	            None => {
1594	                if c == '"' || c == '\'' {
1595	                    quote = Some(c);
1596	                } else if c as u32 == delim as u32 {
1597	                    fields.push(std::mem::take(&mut cur));
1598	                } else {
1599	                    cur.push(c);
1600	                }
1601	            }
1602	        }
1603	    }
1604	    fields.push(cur);
1605	    fields
1606	}
