2295	    /// prevent).
2296	    #[test]
2297	    fn real_bitmaps_and_gifs_are_still_binary_by_magic() {
2298	        // 2x2 24bpp BMP: BITMAPFILEHEADER (14) + BITMAPINFOHEADER (40).
2299	        let mut bmp: Vec<u8> = b"BM".to_vec();
2300	        bmp.extend_from_slice(&70u32.to_le_bytes()); // bfSize
2301	        bmp.extend_from_slice(&[0, 0, 0, 0]); // bfReserved1/2
2302	        bmp.extend_from_slice(&54u32.to_le_bytes()); // bfOffBits
2303	        bmp.extend_from_slice(&40u32.to_le_bytes()); // biSize
2304	        bmp.extend_from_slice(&2i32.to_le_bytes()); // biWidth
2305	        bmp.extend_from_slice(&2i32.to_le_bytes()); // biHeight
2306	        bmp.extend_from_slice(&[1, 0, 24, 0]); // planes, bpp
2307	        bmp.extend(std::iter::repeat_n(0u8, 24));
2308	        // A printable tail that WOULD pass the prose heuristics.
2309	        bmp.extend(b"lorem ipsum dolor sit amet, consectetur adipiscing elit. ".repeat(20));
2310	
2311	        // BITMAPCOREHEADER is the other end of the range that exists.
2312	        let mut bmp_core: Vec<u8> = b"BM".to_vec();
2313	        bmp_core.extend_from_slice(&38u32.to_le_bytes());
2314	        bmp_core.extend_from_slice(&[0, 0, 0, 0]);
2315	        bmp_core.extend_from_slice(&26u32.to_le_bytes()); // 14 + 12
2316	        bmp_core.extend_from_slice(&12u32.to_le_bytes()); // BITMAPCOREHEADER
2317	        bmp_core.extend_from_slice(&[2, 0, 2, 0, 1, 0, 24, 0]);
2318	        bmp_core.extend(b"lorem ipsum dolor sit amet, consectetur adipiscing. ".repeat(20));
2319	
2320	        // GIF89a, 4x4, global colour table of 2 entries, then a Graphic Control
2321	        // extension — introducer 0x21, label 0xF9.
2322	        let mut gif: Vec<u8> = b"GIF89a".to_vec();
2323	        gif.extend_from_slice(&4u16.to_le_bytes()); // width
2324	        gif.extend_from_slice(&4u16.to_le_bytes()); // height
2325	        gif.push(0x80); // GCT present, 2 entries
2326	        gif.push(0); // background colour index
2327	        gif.push(0); // pixel aspect ratio
2328	        gif.extend_from_slice(&[0, 0, 0, 0xff, 0xff, 0xff]); // GCT
2329	                                                             // Graphic Control Extension: the spec fixes the block size at 4.
2330	                                                             // Round 1 stopped at the label, which is why prose carrying a
2331	                                                             // windows-1252 0xF9 satisfied it (#379).
2332	        gif.extend_from_slice(&[0x21, 0xf9, 0x04]);
2333	        gif.extend(b"lorem ipsum dolor sit amet, consectetur adipiscing elit. ".repeat(20));
2334	
2335	        // GIF87a with no global colour table, opening straight on an Image
2336	        // Descriptor: introducer 0x2C, then left/top/width/height/packed for a
2337	        // frame that fills the 16x16 canvas.
2338	        let mut gif87: Vec<u8> = b"GIF87a".to_vec();
2339	        // GCT flag set (2 entries): a frame with no Local Colour Table has to
