2380	    /// True negatives for the regression round 1 of #379 shipped: real GIF
2381	    /// header shapes that the "Pixel Aspect Ratio and Background Colour Index
2382	    /// must be zero" qualifier REFUSED, sending a real image down the text
2383	    /// path to be sectioned into prose records.
2384	    ///
2385	    /// Both shapes are transcribed from real files on the build machine, not
2386	    /// invented — which is the point, since
2387	    /// `real_bitmaps_and_gifs_are_still_binary_by_magic` builds ideal headers
2388	    /// and therefore could not see this class at all:
2389	    ///
2390	    ///   * `docs/media/demo.gif`, this repository's own 3.27 MB demo:
2391	    ///     720x450, packed `0xF7`, background `0xFF`, **aspect `0x31`**, a
2392	    ///     768-byte global colour table, then the `0x21 0xFF` NETSCAPE2.0
2393	    ///     application extension that every animated GIF carries. `0x31` is
2394	    ///     not corruption, it is the spec's encoding of a 1:1 pixel ratio:
2395	    ///     `(49 + 15) / 64 = 1.0`.
2396	    ///   * a 92 KB screen capture with the **GCT flag clear and background
2397	    ///     index 255**, which the spec says should be 0 when no table is
2398	    ///     declared and which real encoders write anyway.
2399	    ///
2400	    /// Two things about the assertion are deliberate. The bodies are printable
2401	    /// (see `printable_payload`), so a refused fixture sniffs `TxtProse` — the
2402	    /// cue for `extract` to turn an image into records — rather than being
2403	    /// rescued by the control-character heuristic and quietly proving nothing.
2404	    /// And the expectation is `Some("gif")`, not merely `Family::Binary`,
2405	    /// because that heuristic is luck, not a fallback: across the 147 real
2406	    /// GIFs measured it clears the 10% threshold by as little as 0.14 points,
2407	    /// and two of them sit under it at 9.39% and 9.78%.
2408	    #[test]
2409	    fn real_gif_shapes_the_aspect_ratio_rule_refused() {
2410	        // demo.gif: GCT present and full size, non-zero background AND aspect.
2411	        let mut animated: Vec<u8> = b"GIF89a".to_vec();
2412	        animated.extend_from_slice(&720u16.to_le_bytes());
2413	        animated.extend_from_slice(&450u16.to_le_bytes());
2414	        animated.push(0xf7); // GCT present, 256 entries -> 768 bytes
2415	        animated.push(0xff); // background colour index
2416	        animated.push(0x31); // pixel aspect ratio: 1:1, NOT "unspecified"
2417	        animated.extend(printable_payload(14).into_iter().take(768));
2418	        // NETSCAPE2.0 loop extension. Application Extension block size is
2419	        // fixed at 11 by the spec ("NETSCAPE" + "2.0").
2420	        animated.extend_from_slice(&[0x21, 0xff, 0x0b]);
2421	        animated.extend(printable_payload(20));
2422	        assert_eq!(animated[781], 0x21, "the first block must land at 13 + 768");
2423	
2424	        // screen capture: GCT flag clear, background index still 255.
2425	        let mut no_table: Vec<u8> = b"GIF89a".to_vec();
2426	        no_table.extend_from_slice(&2184u16.to_le_bytes());
2427	        no_table.extend_from_slice(&1280u16.to_le_bytes());
2428	        no_table.push(0x70); // GCT flag CLEAR
2429	        no_table.push(0xff); // background colour index, spec says 0
2430	        no_table.push(0x00);
2431	        no_table.extend_from_slice(&[0x21, 0xff, 0x0b]);
2432	        no_table.extend(printable_payload(20));
2433	
2434	        for (label, bytes) in [("animated-loop", animated), ("no-global-table", no_table)] {
2435	            let p = Path::new("capture.gif");
2436	            let sn = sniff_bytes(&bytes, p, p, false).unwrap();
2437	            assert_eq!(
2438	                (sn.family, sn.binary_kind.as_deref()),
2439	                (Family::Binary, Some("gif")),
2440	                "{label}: a real GIF header was refused by its qualifier and \
2441	                 fell through to the text heuristics as {:?}/{:?} — this is \
2442	                 #379 inverted, an image turned into prose records",
2443	                sn.family,
2444	                sn.binary_kind
2445	            );
2446	        }
2447	    }
