2563	    /// The Comment-extension arm, which round 2 of #379 added and which an
2564	    /// independent verification then broke real images with. It is the only
2565	    /// branch here carrying a loop, so it is the one that needed fixtures and
2566	    /// did not have them.
2567	    ///
2568	    /// The hazard is specific: `sniff` sees only an 8 KiB prefix
2569	    /// (`read_prefix(.., 8192)`), and a GIF comment may be longer than that.
2570	    /// The first attempt treated "the sub-block chain did not terminate inside
2571	    /// the prefix" as evidence of text, so a real, decodable GIF carrying a
2572	    /// licence notice was handed to the prose extractor — #379 with the sign
2573	    /// flipped.
2574	    ///
2575	    /// This fixture is the MAXIMALLY PACKED shape only. Round 3 then read that
2576	    /// property off this very test and shipped it as the rule ("every size seen
2577	    /// is 0xFF"); `a_streamed_comment_chain_is_not_packed_to_255` below is the
2578	    /// corpus answer to that, and the two must be read together.
2579	    #[test]
2580	    fn a_comment_longer_than_the_sniff_prefix_is_still_a_gif() {
2581	        /// GIF89a, 4x4, 2-entry global colour table, opening on a Comment
2582	        /// Extension of `comment_len` bytes, then a minimal image.
2583	        fn comment_gif(comment_len: usize) -> Vec<u8> {
2584	            let mut g: Vec<u8> = b"GIF89a".to_vec();
2585	            g.extend_from_slice(&4u16.to_le_bytes());
2586	            g.extend_from_slice(&4u16.to_le_bytes());
2587	            g.push(0x80); // GCT present, 2 entries
2588	            g.push(0);
2589	            g.push(0);
2590	            g.extend_from_slice(&[0, 0, 0, 0xff, 0xff, 0xff]); // GCT
2591	            g.extend_from_slice(&[0x21, 0xfe]); // Comment Extension
2592	            let mut left = comment_len;
2593	            while left > 0 {
2594	                let take = left.min(255);
2595	                g.push(take as u8);
2596	                g.extend(std::iter::repeat_n(b'D', take));
2597	                left -= take;
2598	            }
2599	            g.push(0x00); // block terminator
2600	            g.extend_from_slice(&[0x2c, 0, 0, 0, 0, 4, 0, 4, 0, 0, 0x02]);
2601	            g
2602	        }
2603	
2604	        // The last entry outruns `GIF_PREFIX`, so it exercises the arm that
2605	        // decides on how the buffer ran out rather than on the terminator.
2606	        for len in [
2607	            13usize,
2608	            255,
2609	            300,
2610	            4000,
2611	            8_192,
2612	            20_000,
2613	            60_000,
2614	            GIF_PREFIX + 4096,
2615	        ] {
2616	            let g = comment_gif(len);
2617	            // What `sniff` actually gets to see: `sniff_with_name` re-reads a
2618	            // GIF candidate to `GIF_PREFIX`, so this is the whole file or a
2619	            // megabyte of it, never 8 KiB.
2620	            let prefix: Vec<u8> = g.iter().copied().take(GIF_PREFIX).collect();
2621	            let p = Path::new("frame.gif");
2622	            let sn = sniff_bytes(&prefix, p, p, false).unwrap();
2623	            assert_eq!(
2624	                sn.family,
2625	                Family::Binary,
2626	                "comment of {len} B: a real GIF was refused and would be handed \
2627	                 to the prose extractor — this is #379 inverted"
2628	            );
2629	            assert_eq!(sn.binary_kind.as_deref(), Some("gif"), "comment of {len} B");
2630	        }
2631	    }
