2966	    /// The cost of deciding a budget-exhausted chain as an image, pinned so it
2967	    /// is a recorded trade and not a later surprise.
2968	    ///
2969	    /// A file that outruns `GIF_PREFIX` with its chain intact is called an
2970	    /// image, and text reaches that state easily — it has no NUL, so the walk
2971	    /// cannot terminate in it. The entry cost is the header alone: `GIF89a`,
2972	    /// eight bytes forming a Logical Screen Descriptor the earlier checks
2973	    /// accept, then `0x21 0xFE`. `0xFE` is `þ` in windows-1252 and not ASCII,
2974	    /// which is the only part ordinary text lacks — and NOT at a fixed offset:
2975	    /// when the packed byte at 10 has bit 7 set (any accented letter does it)
2976	    /// the Global Colour Table shifts `block` from 13 to one of 19, 25, 37, 61,
2977	    /// 109, 205, 397 or 781 — nine possible slots, of which 13 (no colour
2978	    /// table) is one. An earlier version of this comment said "offset 14" flat;
2979	    /// the correction that replaced it then dropped the no-table case, which is
2980	    /// how the count below was wrong.
2981	    ///
2982	    /// So this is a measured trade against merged `main`, not a free win, and
2983	    /// both sides are pinned here:
2984	    ///
2985	    ///   * `main` keeps 10 corpus text negatives and junks 18 decodable GIFs
2986	    ///     whose canvas high bytes happen to be printable.
2987	    ///   * this rule keeps all 18 GIFs and junks those same 10 text files — but
2988	    ///     only above the budget. At their real sizes every build keeps them as
2989	    ///     text; it is file LENGTH that flips them, which is exactly the blind
2990	    ///     spot the corpus could not show.
2991	    ///
2992	    /// The 10 are the eight `gctflag_ext_fe_p*` (packed bit 7 set, `block` 19)
2993	    /// plus `label_fe_thorn.txt` and `label_fe_then_printable_size.txt` (no
2994	    /// colour table, `block` 13). An earlier version of this comment said
2995	    /// eight, because the class was enumerated from the filenames a reviewer
2996	    /// had supplied rather than from the code path — the same mistake this file
2997	    /// spends fifty lines warning about, made while correcting it. Above the
2998	    /// budget the shipped rule IS round 2's `true`, so the 10 named at that
2999	    /// bullet and the 10 here are necessarily the same set.
3000	    ///
3001	    /// Chosen because the 18 are real artifacts that giflib and Pillow both
3002	    /// decode, while the 8 are fixtures that only reach this state when
3003	    /// inflated 117x. A sweep of 403,716 real files found 66 opening with GIF
3004	    /// magic and none carrying the comment shape at all, so neither class has a
3005	    /// measured natural base rate — which is the honest reason to write the
3006	    /// trade down rather than claim the rule is safe.
3007	    #[test]
3008	    fn prose_past_the_budget_is_called_an_image_and_prose_under_it_is_not() {
3009	        let mut prose: Vec<u8> = b"GIF89ax".to_vec();
3010	        prose.push(b'\n'); // 7: the canvas high byte round 4 keyed on
3011	        prose.extend_from_slice(b"yzest");
3012	        prose.push(b'!'); // 13
3013	        prose.push(0xfe); // 14: windows-1252 `þ`, the shape's real cost of entry
3014	        prose.push(b'L'); // 15: first sub-block size
3015	        while prose.len() < GIF_PREFIX + 4096 {
3016	            prose.extend_from_slice(
3017	                "Le format GIF est tres ancien et reste partout sur le web. ".as_bytes(),
3018	            );
3019	        }
3020	        let p = Path::new("notes.txt");
3021	
3022	        let under: Vec<u8> = prose.iter().copied().take(200_000).collect();
3023	        assert_eq!(
3024	            sniff_bytes(&under, p, p, false).unwrap().family,
3025	            Family::TxtProse,
3026	            "prose that ends before the budget must stay text"
3027	        );
3028	
3029	        let over: Vec<u8> = prose.iter().copied().take(GIF_PREFIX).collect();
3030	        assert_eq!(
3031	            sniff_bytes(&over, p, p, false).unwrap().family,
3032	            Family::Binary,
3033	            "a chain intact across the whole budget is called an image — if this \
3034	             ever needs to change, change the budget or find evidence the chain \
3035	             can carry, do not go back to guessing from a fixed offset"
3036	        );
3037	
3038	        // The concrete cost, from the corpus itself: the #379 negatives built
3039	        // to represent this exact shape are kept only by being short. This
3040	        // reproduces `gctflag_ext_fe_p80.txt` — packed byte 0x80, so the GCT
3041	        // moves `block` to 19 — and asserts both sides of the length boundary.
3042	        let mut gct: Vec<u8> = b"GIF89a".to_vec();
3043	        gct.extend_from_slice(b"pros"); // 6..10: canvas, four printable bytes
3044	        gct.push(0x80); // 10: packed, GCT flag set by an accented letter
3045	        gct.extend_from_slice(b"st"); // 11, 12
3046	        gct.extend_from_slice(&[0, 0, 0, 0xff, 0xff, 0xff]); // 13..19: the GCT
3047	        gct.push(0x21); // 19: extension introducer, shifted by the GCT
3048	        gct.push(0xfe); // 20: comment label
3049	        gct.push(b' '); // 21: first sub-block size
3050	        while gct.len() < GIF_PREFIX + 4096 {
3051	            gct.extend_from_slice("Le format GIF reste partout sur le web. ".as_bytes());
3052	        }
3053	        let short: Vec<u8> = gct.iter().copied().take(8_960).collect();
3054	        assert_eq!(
3055	            sniff_bytes(&short, p, p, false).unwrap().family,
3056	            Family::TxtProse,
3057	            "at the corpus's own size this file is text on every build"
3058	        );
3059	        let long: Vec<u8> = gct.iter().copied().take(GIF_PREFIX).collect();
3060	        assert_eq!(
3061	            sniff_bytes(&long, p, p, false).unwrap().family,
3062	            Family::Binary,
3063	            "the same bytes past the budget are junked as an image — this is the \
3064	             cost of the rule, and merged main does NOT pay it. Keeping this \
3065	             assertion honest matters more than keeping it green: if a future \
3066	             change makes it text, re-measure the 18 GIFs on the other side"
3067	        );
3068	
3069	        // The other two, which the first version of this test did not cover:
3070	        // no Global Colour Table, so `block` stays at 13 and the `21 FE` pair
3071	        // sits at 13/14 — the literal "offset 14" shape. Reproduces
3072	        // `label_fe_thorn.txt`, and it is why the trade costs 10 files, not 8.
3073	        let mut flat: Vec<u8> = b"GIF89a fichie".to_vec(); // 0..13, packed at 10
3074	        assert_eq!(flat[10] & 0x80, 0, "no colour table, so block stays 13");
3075	        flat.push(0x21); // 13
3076	        flat.push(0xfe); // 14
3077	        flat.push(b'L'); // 15
3078	        while flat.len() < GIF_PREFIX + 4096 {
3079	            flat.extend_from_slice("Le format GIF reste partout sur le web. ".as_bytes());
3080	        }
3081	        assert_eq!(
3082	            sniff_bytes(&flat[..8_960], p, p, false).unwrap().family,
3083	            Family::TxtProse,
3084	            "at its corpus size the no-table shape is text on every build"
3085	        );
3086	        assert_eq!(
3087	            sniff_bytes(&flat[..GIF_PREFIX], p, p, false)
3088	                .unwrap()
3089	                .family,
3090	            Family::Binary,
3091	            "the no-table shape pays the same cost past the budget — if this is \
