3239	    /// The invariant itself, walked over every row of `MAGIC_TABLE` rather than
3240	    /// asserted about the two rows this issue happened to name: a signature
3241	    /// made only of printable ASCII must REFUSE a prefix that is that signature
3242	    /// followed by ordinary prose. A new row wired to `accept` fails here.
3243	    ///
3244	    /// The counter is not decoration — without it a table whose printable rows
3245	    /// all disappeared would pass this test by iterating over nothing.
3246	    ///
3247	    /// SCOPE: `MAGIC_TABLE` only. Three signatures are matched earlier, as
3248	    /// early returns in `sniff_bytes` — see
3249	    /// `signatures_matched_before_the_table` below for what that leaves open.
3250	    #[test]
3251	    fn every_printable_signature_carries_a_qualifier() {
3252	        let mut printable_rows = 0;
3253	        for &(magic, kind, qualify) in MAGIC_TABLE {
3254	            let printable = magic.iter().all(|b| b.is_ascii_graphic() || *b == b' ');
3255	            if !printable {
3256	                continue;
3257	            }
3258	            printable_rows += 1;
3259	            let mut sentence = magic.to_vec();
3260	            sentence.extend(
3261	                " is a magic number that identifies a media file format, and this \
3262	                 sentence is about it rather than an instance of it. "
3263	                    .repeat(30)
3264	                    .as_bytes(),
3265	            );
3266	            assert!(
3267	                !qualify(&sentence),
3268	                "{kind}: the printable signature {:?} accepts a prefix that is \
3269	                 that signature followed by prose — it needs a structural \
3270	                 qualifier (#379/#380)",
3271	                String::from_utf8_lossy(magic)
3272	            );
3273	            let p = Path::new("notes.txt");
3274	            let sn = sniff_bytes(&sentence, p, p, false).unwrap();
3275	            assert_ne!(
3276	                sn.family,
3277	                Family::Binary,
3278	                "{kind}: prose opening with {:?} was junked",
3279	                String::from_utf8_lossy(magic)
3280	            );
3281	        }
3282	        assert!(
3283	            printable_rows >= 7,
3284	            "expected the printable signatures (GIF8, BM, 8BPS, RIFF, OggS, \
3285	             fLaC, ID3, Kaydara FBX Binary) to be walked; saw {printable_rows} \
3286	             — did the table lose rows, or did this filter stop matching?"
3287	        );
3288	    }
