3290	    /// `%PDF-`, `SQLite format 3\0` and `PK\x03\x04` never reach `MAGIC_TABLE`
3291	    /// — they are early returns in `sniff_bytes` — so the walk above says
3292	    /// nothing about them. Two of the three are safe for the usual reason (a
3293	    /// byte text cannot contain: the NUL after `3`, and `\x03\x04`), and this
3294	    /// pins that. `%PDF-` needed its own structural qualifier (`pdf_header`,
3295	    /// #403 — same class as #379/#380) since all five of its bytes are
3296	    /// printable ASCII; this pins that prose opening with the bare signature
3297	    /// now reads `TxtProse`, not `Pdf`.
3298	    #[test]
3299	    fn signatures_matched_before_the_table() {
3300	        for (label, opener, want) in [
3301	            (
3302	                "sqlite",
3303	                "SQLite format 3 is the string at the start of every database file. ",
3304	                Family::TxtProse,
3305	            ),
3306	            (
3307	                "zip",
3308	                "PK is the local file header signature of the ZIP format. ",
3309	                Family::TxtProse,
3310	            ),
3311	            (
3312	                "pdf",
3313	                "%PDF- is the five byte header every PDF file begins with. ",
3314	                Family::TxtProse,
3315	            ),
3316	        ] {
3317	            let text = opener.repeat(30);
3318	            let p = Path::new("notes.txt");
3319	            let sn = sniff_bytes(text.as_bytes(), p, p, false).unwrap();
3320	            assert_eq!(
3321	                sn.family, want,
3322	                "{label}: prose opening with a pre-table signature classified \
3323	                 {:?}/{:?}",
3324	                sn.family, sn.binary_kind
3325	            );
3326	        }
3327	    }
3328	
3329	    /// The positive control `every_printable_signature_carries_a_qualifier`
3330	    /// cannot provide for `%PDF-`, since it walks `MAGIC_TABLE` only: a real
3331	    /// PDF header must still classify `Family::Pdf`, or `pdf_header` is not a
3332	    /// qualifier but a second way to break the format.
3333	    #[test]
3334	    fn a_real_pdf_header_still_classifies_as_pdf() {
3335	        let headers: [&[u8]; 3] = [
3336	            b"%PDF-1.7\n%\xE2\xE3\xCF\xD3\n1 0 obj\n",
3337	            b"%PDF-1.4\r\n1 0 obj\n",
3338	            b"%PDF-2.0\r%comment\r",
3339	        ];
3340	        for header in headers {
3341	            let p = Path::new("doc.pdf");
3342	            let sn = sniff_bytes(header, p, p, false).unwrap();
3343	            assert_eq!(
3344	                sn.family,
3345	                Family::Pdf,
3346	                "real PDF header {header:?} classified {:?}/{:?} — pdf_header \
3347	                 rejected a spec-conformant file",
3348	                sn.family,
3349	                sn.binary_kind
3350	            );
3351	        }
3352	    }
3353	}
