1	//! Built-in transform plugins — no WASM required.
2	//!
3	//! Every plugin implements [`TransformPlugin`] and can be composed into a
4	//! [`Pipeline`](crate::pipeline::Pipeline).
5	
6	use std::collections::HashMap;
7	
