14	// ─────────────────────────────────────────────────────────────────────────────
15	// JsonParsePlugin
16	// ─────────────────────────────────────────────────────────────────────────────
17	
18	/// Parse the value of a string field as JSON.
19	///
20	/// If `target` is empty the parsed fields are merged into the root document.
21	/// Otherwise the parsed object is stored at `doc[target]`.
22	///
23	/// The original field is removed after successful parsing.
24	pub struct JsonParsePlugin {
25	    /// Source field name containing the raw JSON string.
26	    field: String,
27	    /// Destination field (empty ⇒ merge into root).
28	    target: String,
29	}
30	
31	impl JsonParsePlugin {
32	    pub fn new(field: impl Into<String>, target: impl Into<String>) -> Self {
33	        Self {
34	            field: field.into(),
35	            target: target.into(),
36	        }
37	    }
38	}
39	
40	impl TransformPlugin for JsonParsePlugin {
41	    fn name(&self) -> &str {
42	        "json_parse"
43	    }
44	
45	    fn process(&self, doc: &mut Value) -> ProcessAction {
46	        let raw = match doc.get(&self.field).and_then(Value::as_str) {
47	            Some(s) => s.to_owned(),
48	            None => return ProcessAction::Pass,
49	        };
50	
51	        match serde_json::from_str::<Value>(&raw) {
52	            Ok(parsed) => {
53	                // Remove source field.
54	                if let Some(obj) = doc.as_object_mut() {
55	                    obj.remove(&self.field);
56	                }
57	
58	                if self.target.is_empty() {
59	                    // Merge into root.
60	                    if let (Some(root), Some(parsed_obj)) =
61	                        (doc.as_object_mut(), parsed.as_object())
62	                    {
63	                        for (k, v) in parsed_obj {
64	                            root.insert(k.clone(), v.clone());
65	                        }
66	                    }
67	                } else {
68	                    doc[&self.target] = parsed;
69	                }
70	                ProcessAction::Pass
71	            }
72	            Err(e) => {
73	                debug!(field = self.field.as_str(), error = %e, "json_parse: failed to parse field");
74	                ProcessAction::Pass // leave doc unchanged on parse failure
75	            }
76	        }
77	    }
78	}
