199	/// Rename document fields.
200	///
201	/// `mappings` maps `old_name → new_name`.  Fields not present in the document
202	/// are silently skipped.
203	pub struct FieldRenamePlugin {
204	    mappings: HashMap<String, String>,
205	}
206	
207	impl FieldRenamePlugin {
208	    pub fn new(mappings: HashMap<String, String>) -> Self {
209	        Self { mappings }
210	    }
211	}
