213	impl TransformPlugin for FieldRenamePlugin {
214	    fn name(&self) -> &str {
215	        "field_rename"
216	    }
217	
218	    fn process(&self, doc: &mut Value) -> ProcessAction {
219	        if let Some(obj) = doc.as_object_mut() {
220	            for (old, new) in &self.mappings {
221	                if let Some(val) = obj.remove(old.as_str()) {
222	                    obj.insert(new.clone(), val);
223	                }
224	            }
225	        }
226	        ProcessAction::Pass
227	    }
228	}
