479	// ─────────────────────────────────────────────────────────────────────────────
480	// PiiRedactionPlugin
481	// ─────────────────────────────────────────────────────────────────────────────
482	
483	/// Redact PII from string fields in a document.
484	///
485	/// Supported PII types:
486	/// - `email` — e.g. `user@example.com` → `[REDACTED_EMAIL]`
487	/// - `ip` — IPv4 and IPv6 addresses → `[REDACTED_IP]`
488	/// - `credit_card` — 13–19 digit numbers with optional separators →
489	///   `[REDACTED_CC]`
490	/// - `ssn` — US Social Security Numbers (`NNN-NN-NNNN`) → `[REDACTED_SSN]`
491	/// - `phone` — common phone number patterns → `[REDACTED_PHONE]`
492	pub struct PiiRedactionPlugin {
493	    /// Compiled `(regex, replacement)` pairs.
494	    patterns: Vec<(Regex, &'static str)>,
495	}
496	
497	/// PII type names this plugin knows how to redact.
498	///
499	/// A name outside this list used to be accepted and then quietly matched
500	/// nothing: `PiiRedactionPlugin::new(vec!["social_security".into()])` compiled
501	/// to an EMPTY pattern set, so the stage ran on every document, redacted
502	/// nothing, and reported success — unredacted PII in the index with no signal
503	/// anywhere (issue #204). `build_plugin` now rejects unknown names at
504	/// pipeline-creation time.
505	pub const PII_TYPE_NAMES: &[&str] = &["email", "ip", "credit_card", "ssn", "phone"];
506	
507	impl PiiRedactionPlugin {
508	    /// Build a new plugin that redacts the given PII types.
509	    ///
510	    /// `types` is a list of strings from [`PII_TYPE_NAMES`]. An empty list
511	    /// enables all types. Callers must validate the names first (see
512	    /// `build_plugin`) — an unknown name silently contributes no pattern.
513	    pub fn new(types: Vec<String>) -> Self {
514	        let all = types.is_empty();
515	
516	        let mut patterns = Vec::new();
517	
518	        let wants = |t: &str| all || types.iter().any(|s| s == t);
519	
520	        if wants("email") {
521	            patterns.push((
522	                Regex::new(r"(?i)[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}").unwrap(),
523	                "[REDACTED_EMAIL]",
524	            ));
525	        }
526	        if wants("ip") {
527	            // IPv4
528	            patterns.push((
529	                Regex::new(r"\b(?:\d{1,3}\.){3}\d{1,3}\b").unwrap(),
530	                "[REDACTED_IP]",
531	            ));
532	            // IPv6 (simplified)
533	            patterns.push((
534	                Regex::new(r"(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}").unwrap(),
535	                "[REDACTED_IP]",
536	            ));
537	        }
538	        if wants("credit_card") {
539	            patterns.push((
540	                Regex::new(r"\b(?:\d[ \-]?){13,19}\b").unwrap(),
541	                "[REDACTED_CC]",
542	            ));
543	        }
544	        if wants("ssn") {
545	            patterns.push((
546	                Regex::new(r"\b\d{3}-\d{2}-\d{4}\b").unwrap(),
547	                "[REDACTED_SSN]",
548	            ));
549	        }
550	        if wants("phone") {
551	            patterns.push((
552	                Regex::new(r"\b(?:\+?1[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}\b").unwrap(),
553	                "[REDACTED_PHONE]",
554	            ));
555	        }
556	
557	        Self { patterns }
558	    }
559	
560	    /// Redact PII from a single string.
561	    fn redact_str(&self, s: &str) -> String {
562	        let mut result = s.to_string();
563	        for (re, replacement) in &self.patterns {
564	            result = re.replace_all(&result, *replacement).into_owned();
565	        }
566	        result
567	    }
568	
569	    /// Recursively redact all string values in a JSON value.
570	    fn redact_value(&self, v: &mut Value) {
571	        match v {
572	            Value::String(s) => {
573	                *s = self.redact_str(s);
574	            }
575	            Value::Object(obj) => {
576	                for val in obj.values_mut() {
577	                    self.redact_value(val);
578	                }
579	            }
580	            Value::Array(arr) => {
581	                for item in arr.iter_mut() {
582	                    self.redact_value(item);
583	                }
584	            }
585	            _ => {}
586	        }
587	    }
588	}
589	
590	impl TransformPlugin for PiiRedactionPlugin {
591	    fn name(&self) -> &str {
592	        "pii_redaction"
593	    }
594	
595	    fn process(&self, doc: &mut Value) -> ProcessAction {
596	        self.redact_value(doc);
597	        ProcessAction::Pass
598	    }
599	}
