637	// ConvertTypePlugin
638	// ─────────────────────────────────────────────────────────────────────────────
639	
640	/// Target types the `convert` stage can produce.
641	///
642	/// An unknown target type used to be accepted at pipeline-creation time and
643	/// then hit `_ => None` per document: the field was left exactly as it was and
644	/// the document passed. `"type": "int"` (instead of `"integer"`) therefore
645	/// produced a pipeline that acknowledged the conversion and never performed it
646	/// (issue #204). `build_plugin` now rejects unknown target types.
647	pub const CONVERT_TARGET_TYPES: &[&str] = &["integer", "float", "string", "boolean"];
648	
649	/// Convert a field's value to a different type.
650	///
651	/// Supported target types are [`CONVERT_TARGET_TYPES`]; an unknown one is
652	/// rejected when the pipeline is created. If the *value* cannot be coerced
653	/// (e.g. `"abc"` to `integer`) the document is passed through unchanged — a
654	/// per-document data condition, not a configuration error. (ES's `convert`
655	/// processor fails the document instead; that divergence is pre-existing and
656	/// out of scope for the #204 sweep.)
657	pub struct ConvertTypePlugin {
658	    field: String,
659	    target_type: String,
660	}
661	
662	impl ConvertTypePlugin {
663	    pub fn new(field: impl Into<String>, target_type: impl Into<String>) -> Self {
664	        Self {
665	            field: field.into(),
666	            target_type: target_type.into(),
667	        }
668	    }
669	}
670	
671	impl TransformPlugin for ConvertTypePlugin {
672	    fn name(&self) -> &str {
673	        "convert"
674	    }
675	
676	    fn process(&self, doc: &mut Value) -> ProcessAction {
677	        let current = match doc.get(&self.field).cloned() {
678	            Some(v) => v,
679	            None => return ProcessAction::Pass,
680	        };
681	
682	        let converted = match self.target_type.as_str() {
683	            "integer" => {
684	                let n = match &current {
685	                    Value::Number(n) => n.as_i64(),
686	                    Value::String(s) => s.trim().parse::<i64>().ok(),
687	                    Value::Bool(b) => Some(if *b { 1 } else { 0 }),
688	                    _ => None,
689	                };
690	                n.map(|i| Value::Number(serde_json::Number::from(i)))
691	            }
692	            "float" => {
693	                let f = match &current {
694	                    Value::Number(n) => n.as_f64(),
695	                    Value::String(s) => s.trim().parse::<f64>().ok(),
696	                    Value::Bool(b) => Some(if *b { 1.0 } else { 0.0 }),
697	                    _ => None,
698	                };
699	                f.and_then(|f| serde_json::Number::from_f64(f).map(Value::Number))
700	            }
701	            "string" => {
702	                let s = match &current {
703	                    Value::String(s) => Some(s.clone()),
704	                    Value::Number(n) => Some(n.to_string()),
705	                    Value::Bool(b) => Some(b.to_string()),
706	                    Value::Null => Some("null".to_string()),
707	                    _ => None,
708	                };
709	                s.map(Value::String)
710	            }
711	            "boolean" => {
712	                let b = match &current {
713	                    Value::Bool(b) => Some(*b),
714	                    Value::String(s) => match s.to_lowercase().as_str() {
715	                        "true" | "1" | "yes" | "on" => Some(true),
716	                        "false" | "0" | "no" | "off" => Some(false),
717	                        _ => None,
718	                    },
719	                    Value::Number(n) => n.as_i64().map(|i| i != 0),
720	                    _ => None,
721	                };
722	                b.map(Value::Bool)
723	            }
724	            _ => None,
725	        };
726	
727	        if let Some(v) = converted {
728	            doc[&self.field] = v;
729	        }
730	        ProcessAction::Pass
731	    }
732	}
