28	/// Total decompressed cap for one zip. Real advisory dumps are well under
29	/// this; the cap exists because a zip's declared sizes are untrusted and a
30	/// 3 MiB file can claim to expand to terabytes.
31	const MAX_EXTRACT_BYTES: u64 = 2 << 30;
