34	pub struct Fetched {
35	    /// The directory the glob walk starts from.
36	    pub root: PathBuf,
37	    /// Current upstream version marker, if the kind has one.
38	    pub watermark: Option<String>,
39	    /// The watermark matches the previous run's: the caller should skip
40	    /// walking AND pruning this source (everything it stored is still live).
41	    pub unchanged: bool,
42	}
