49	/// Materialize a source. `cache_dir` is `<build>/cache`; it only exists to
50	/// make network kinds incremental.
51	pub fn fetch(src: &SourceSpec, recipe_dir: &Path, cache_dir: &Path) -> Result<Fetched> {
52	    match src.kind {
53	        super::recipe::SourceKind::Dir => Ok(Fetched {
54	            root: recipe_dir.join(src.path.as_deref().unwrap_or(".")),
55	            watermark: None,
56	            unchanged: false,
57	        }),
58	        super::recipe::SourceKind::HttpZip => {
59	            let url = src.url.as_deref().unwrap_or_default();
60	            let zip_path = cache_dir.join(format!("{}.zip", src.slug));
61	            httpget::download(url, &zip_path)
62	                .with_context(|| format!("source '{}': fetch", src.slug))?;
63	            let root = cache_dir.join(&src.slug);
64	            extract_zip(&zip_path, &root)
65	                .with_context(|| format!("source '{}': extract", src.slug))?;
66	            Ok(Fetched {
67	                root,
68	                watermark: None,
69	                unchanged: false,
70	            })
71	        }
72	        super::recipe::SourceKind::Git => {
73	            let url = src.url.as_deref().unwrap_or_default();
74	            let root = cache_dir.join(&src.slug);
75	            let rev = src.rev.as_deref().unwrap_or("HEAD");
76	            let watermark = git_checkout(&root, url, rev, &src.slug)?;
77	            let prev = std::fs::read_to_string(watermark_path(cache_dir, &src.slug))
78	                .map(|s| s.trim().to_string())
79	                .unwrap_or_default();
80	            Ok(Fetched {
81	                root,
82	                watermark: Some(watermark.clone()),
83	                unchanged: !watermark.is_empty() && watermark == prev,
84	            })
85	        }
86	    }
87	}
