97	/// Shallow promisor checkout of `rev` into `target`, reusing the
98	/// corpus-clone machinery: init + blob:none filter so a pin at an old sha
99	/// costs one small fetch, never a full history. `rev` is a full sha, a
100	/// branch/tag name, or `HEAD` (the remote's default). Returns HEAD.
101	fn git_checkout(target: &Path, url: &str, rev: &str, slug: &str) -> Result<String> {
102	    if !target.join(".git").exists() {
103	        std::fs::create_dir_all(target)
104	            .with_context(|| format!("source '{slug}': create {}", target.display()))?;
105	        crate::xc::git(Some(target), &["init", "--quiet"])?;
106	        crate::xc::git(Some(target), &["remote", "add", "origin", url]).ok();
107	        crate::xc::git(Some(target), &["config", "remote.origin.promisor", "true"]).ok();
108	        crate::xc::git(
109	            Some(target),
110	            &["config", "remote.origin.partialclonefilter", "blob:none"],
111	        )
112	        .ok();
113	    }
114	    // A pinned rev (full sha) can reuse checkout_at_sha; a named ref (branch
115	    // or tag, e.g. RustSec's `osv` branch) and plain HEAD go through
116	    // FETCH_HEAD, which checkout_at_sha cannot name. Anything else used to
117	    // silently fetch HEAD — a typo'd branch name now fails loudly instead.
118	    let ok = |r: Result<(i32, String)>| r.map(|(rc, _)| rc == 0).unwrap_or(false);
119	    let looks_like_sha = rev.len() == 40 && rev.chars().all(|c| c.is_ascii_hexdigit());
120	    if looks_like_sha {
121	        crate::xc::checkout_at_sha(target, url, rev)
122	            .with_context(|| format!("source '{slug}': checkout {rev}"))?;
123	    } else {
124	        // `rev` works directly as the refspec: a branch/tag name fetches that
125	        // ref, and the literal "HEAD" fetches the remote's default HEAD.
126	        if !ok(crate::xc::git(
127	            Some(target),
128	            &["fetch", "--depth", "1", "origin", rev],
129	        )) {
130	            bail!("source '{slug}': git fetch {rev} from {url} failed");
131	        }
132	        if !ok(crate::xc::git(
133	            Some(target),
134	            &["checkout", "--quiet", "--force", "--detach", "FETCH_HEAD"],
135	        )) {
136	            bail!("source '{slug}': git checkout FETCH_HEAD ({rev}) failed");
137	        }
138	        crate::xc::git(Some(target), &["clean", "-qfd"]).ok();
139	    }
140	    let (_, head) = crate::xc::git(Some(target), &["rev-parse", "HEAD"])
141	        .with_context(|| format!("source '{slug}': rev-parse"))?;
142	    if head.is_empty() {
143	        bail!("source '{slug}': empty HEAD after checkout");
144	    }
145	    Ok(head)
146	}
