148	/// Extract `zip` into `dest`, replacing any previous extraction of the same
149	/// source. Defensive: entry paths are sanitized, escapes are skipped and
150	/// counted (returned), total decompressed bytes are capped.
151	pub fn extract_zip(zip: &Path, dest: &Path) -> Result<usize> {
152	    let f = std::fs::File::open(zip).with_context(|| format!("open {}", zip.display()))?;
153	    let mut z = zip::ZipArchive::new(f).context("open zip")?;
154	
155	    // clear the previous extraction first: a file renamed upstream must not
156	    // survive as a stale duplicate
157	    if dest.exists() {
158	        std::fs::remove_dir_all(dest).with_context(|| format!("clear {}", dest.display()))?;
159	    }
160	    std::fs::create_dir_all(dest)?;
161	
162	    let mut skipped = 0usize;
163	    let mut total: u64 = 0;
164	    for i in 0..z.len() {
165	        let mut entry = z.by_index(i).context("zip entry")?;
166	        if entry.is_dir() {
167	            continue;
168	        }
169	        if entry.is_symlink() {
170	            skipped += 1;
171	            continue;
172	        }
173	        let raw = entry.name().to_string();
174	        let Some(safe) = sanitize_entry_path(&raw) else {
175	            skipped += 1;
176	            continue;
177	        };
178	        let out = dest.join(&safe);
179	        if let Some(parent) = out.parent() {
180	            std::fs::create_dir_all(parent)?;
181	        }
182	        let mut buf = Vec::new();
183	        // bounded read: `entry.size()` is the DECLARED size, so read via
184	        // take() + counter and stop the whole extraction past the cap
185	        let limit = MAX_EXTRACT_BYTES.saturating_sub(total);
186	        let mut reader = (&mut entry).take(limit + 1);
187	        reader.read_to_end(&mut buf).context("decompress entry")?;
188	        total += buf.len() as u64;
189	        if total > MAX_EXTRACT_BYTES {
190	            bail!(
191	                "zip {} expands past the {} cap",
192	                zip.display(),
193	                MAX_EXTRACT_BYTES
194	            );
195	        }
196	        std::fs::write(&out, &buf)?;
197	    }
198	    Ok(skipped)
199	}
