201	/// Reject absolute paths, drive letters, `..`, and anything not expressible
202	/// as normal relative components (the zip-slip family). Returns the
203	/// posix-style relative path. Windows-style names (`C:/x`, `a\\b`) are
204	/// rejected on EVERY os — a pack may be built anywhere, and a name that is
205	/// a harmless subdir on linux is an escape on windows.
206	fn sanitize_entry_path(raw: &str) -> Option<String> {
207	    let path = Path::new(raw);
208	    let mut parts: Vec<&str> = Vec::new();
209	    for c in path.components() {
210	        match c {
211	            Component::Normal(p) => {
212	                let s = p.to_str()?;
213	                if s.is_empty()
214	                    || s == "."
215	                    || s.contains('\0')
216	                    || s.contains(':')
217	                    || s.contains('\\')
218	                {
219	                    return None;
220	                }
221	                parts.push(s);
222	            }
223	            // a leading `/` makes it absolute on unix; Prefix is a windows
224	            // drive; CurDir/ParentDir have no business in an entry name
225	            _ => return None,
226	        }
227	    }
228	    if parts.is_empty() {
229	        return None;
230	    }
231	    Some(parts.join("/"))
232	}
