95	    let _permit = worker_gate().acquire();
96	    let response = spawn_worker(path)?;
97	    // Counted only once the worker has produced a usable protocol response.
98	    // An invocation that spawned and then failed, timed out, or was killed is
99	    // deliberately excluded — hence `..._responses` and not `..._calls` in the
100	    // report. Total parser *invocations* are not a number this counter can
101	    // honestly supply.
