/// Query parameters for the auto-ID index endpoint.
#[derive(Debug, Default, Deserialize)]
pub struct IndexDocAutoParams {
    /// `refresh=true|wait_for` — accepted without error; memtable is always visible.
    pub refresh: Option<String>,
    /// `pipeline=my_pipeline` — ingest pipeline to run before indexing.
    /// `_none` disables the index's `default_pipeline`; absent falls back to it.
    pub pipeline: Option<String>,
}

/// Resolve the effective ingest pipeline for a single-doc write.
///
/// Mirrors Elasticsearch `index.default_pipeline` semantics:
/// - `Some("_none")` → `None` (explicit opt-out; no pipeline runs).
/// - `Some(name)`    → that pipeline (an explicit `?pipeline=` always wins).
/// - `None`          → the index's `index.default_pipeline` setting, if any.
///
/// The default is read by [`xerj_engine::Engine::default_pipeline_for`], which
/// `_bulk` also uses — one lookup, so the two forms of the same write cannot
/// disagree about which pipeline applies.
fn resolve_effective_pipeline(
    state: &AppState,
    index: &str,
    explicit: Option<&str>,
) -> Option<String> {
    match explicit {
        Some("_none") => None,
        Some(p) => Some(p.to_string()),
        None => state.engine.default_pipeline_for(index),
    }
}

/// Fast path for `POST /{index}/_doc`: receives raw bytes to skip the axum
/// JSON extractor's extra validation pass and parse directly with simd_json /
/// serde_json.  No schema validation is performed here; the engine layer handles
/// all type coercion.  This shaves ~15–30 µs of extractor overhead per doc.
pub async fn index_doc_auto(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<IndexDocAutoParams>,
    body: bytes::Bytes,
) -> impl IntoResponse {
    // Parse the raw body directly — avoids the axum Json extractor's extra
    // content-type enforcement and serde_json::from_str double-pass.
    let doc: Value = match serde_json::from_slice(&body) {
        Ok(v) => v,
        Err(e) => {
            return ApiError::new(xerj_common::XerjError::invalid_query(format!(
                "invalid JSON body: {e}"
