/// True when the mirror already holds this object's bytes at the right size.
fn mirror_file_ready(mirror: &Path, rel: &str, size: u64) -> bool {
    std::fs::metadata(mirror.join(rel)).is_ok_and(|m| m.is_file() && m.len() == size)
